"use client"

import * as React from "react"
import { Checkbox as CheckboxPrimitive } from "radix-ui"

import { cn } from "@/lib/utils"
import { IconCheck as CheckIcon } from "@tabler/icons-react"

function Checkbox({
  className,
  checked,
  defaultChecked,
  onCheckedChange,
  readOnly = false,
  indicator,
  ...props
}: React.ComponentProps<typeof CheckboxPrimitive.Root> & {
  indicator?: React.ReactNode;
  readOnly?: boolean;
}) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      aria-readonly={readOnly || undefined}
      className={cn(
        "peer relative flex size-4 shrink-0 items-center justify-center rounded-[4px] border border-input transition-colors outline-none group-has-disabled/field:opacity-50 after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 aria-invalid:aria-checked:border-primary dark:bg-input/30 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 data-checked:border-primary data-checked:bg-primary data-checked:text-primary-foreground dark:data-checked:bg-primary",
        className
      )}
      checked={readOnly ? checked ?? defaultChecked ?? false : checked}
      defaultChecked={readOnly ? undefined : defaultChecked}
      onCheckedChange={readOnly ? undefined : onCheckedChange}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="grid place-content-center text-current transition-none [&>svg]:size-3.5"
      >
        {indicator ?? <CheckIcon />}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}

export { Checkbox }
